212	        assertThatThrownBy(() -> service.createLock(requestId(), new LockRequest("ghost", 1, 0L)))
213	                .isInstanceOfSatisfying(ApiException.class,
214	                        e -> assertThat(e.getStatus()).isEqualTo(404));
