286	    @Test
287	    void sameRequestIdAndParamsReplaysOriginalResult() {
288	        String rid = requestId();
289	        RegisterArtifactRequest request = artifact("app", 1, dep("lib", 1, 1));
290	        ArtifactResponse first = service.registerArtifact(rid, request);
