340	    @Test
341	    void concurrentSameRequestIdSamePayloadResolvesToSingleResult() throws Exception {
342	        int threads = 8;
343	        ExecutorService pool = Executors.newFixedThreadPool(threads);
344	        CyclicBarrier barrier = new CyclicBarrier(threads);
345	        String rid = requestId();
346	        RegisterArtifactRequest request = artifact("concurrent", 1);
347	
348	        List<Future<ArtifactResponse>> futures = new ArrayList<>();
349	        for (int i = 0; i < threads; i++) {
350	            futures.add(pool.submit(() -> {
351	                barrier.await(5, TimeUnit.SECONDS);
352	                return service.registerArtifact(rid, request);
353	            }));
354	        }
355	        pool.shutdown();
356	
357	        ArtifactResponse first = futures.get(0).get(30, TimeUnit.SECONDS);
358	        for (Future<ArtifactResponse> future : futures) {
359	            ArtifactResponse response = future.get(30, TimeUnit.SECONDS);
360	            assertThat(response.repositoryVersion()).isEqualTo(first.repositoryVersion());
361	            assertThat(response.createdAt()).isEqualTo(first.createdAt());
362	        }
