370	    @Test
371	    void concurrentSameRequestIdDifferentPayloadOneWinsRestConflict() throws Exception {
372	        int threads = 6;
373	        ExecutorService pool = Executors.newFixedThreadPool(threads);
374	        CyclicBarrier barrier = new CyclicBarrier(threads);
375	        String rid = requestId();
376	
377	        List<Future<Integer>> futures = new ArrayList<>();
378	        for (int i = 0; i < threads; i++) {
379	            final int idx = i;
380	            futures.add(pool.submit(() -> {
381	                barrier.await(5, TimeUnit.SECONDS);
382	                try {
383	                    service.registerArtifact(rid, artifact("v" + idx, 1));
384	                    return 201;
385	                } catch (ApiException e) {
386	                    return e.getStatus();
387	                }
388	            }));
389	        }
390	        pool.shutdown();
391	
392	        int success = 0;
393	        int conflict = 0;
394	        for (Future<Integer> future : futures) {
395	            int status = future.get(30, TimeUnit.SECONDS);
396	            assertThat(status).isIn(201, 409);
397	            if (status == 201) {
398	                success++;
399	            } else {
400	                conflict++;
401	            }
402	        }
403	        assertThat(success).isEqualTo(1);
404	        assertThat(conflict).isEqualTo(threads - 1);
405	        assertThat(jdbcTemplate.queryForObject(
406	                "SELECT COUNT(1) FROM artifact", Integer.class)).isEqualTo(1);
407	    }
